-- PolarDB-X: the three HAVING cond->FALSE pairs of the first campaign (seeds 4, 5, 7 of
-- bridge/gen_mysql_db.py), each with its arms alone.  The original, the mutant, then the arms.
-- expected: seed 4 and 5 mutants empty (an INTERSECT with an empty arm); seed 7 mutant = the
-- distinct values of t3.c9 (an EXCEPT of an empty arm); the arms with HAVING 1 = 0 empty.
DROP DATABASE IF EXISTS vs_hf4; CREATE DATABASE vs_hf4; USE vs_hf4;
CREATE TABLE t1 (c1 BIGINT, c4 VARCHAR(20) COLLATE utf8mb4_general_ci) ENGINE=InnoDB;
INSERT INTO t1 VALUES (NULL, 'a '), (2, 'a '), (10, '-3'), (-1, 'x'), (2, 'b'), (1, NULL), (NULL, ''), (-1, '4'), (-3, ' 1'), (7, NULL), (3, ''), (10, '3'), (4, 'b'), (1, ' 1'), (4, 'B'), (-3, NULL);
CREATE TABLE t2 (c1 VARCHAR(20) COLLATE utf8mb4_general_ci, c2 INT, c3 DOUBLE, c14 DECIMAL(10,2), c15 INT, rid INT PRIMARY KEY) ENGINE=InnoDB;
INSERT INTO t2 VALUES ('a ', 2, 5, 5.75, NULL, 0), ('b', 0, 2, 3.25, NULL, 1), ('a', 1, 2, -1, -3, 2), ('', 1, 0, NULL, 5, 3), (NULL, 10, 3.25, 10, 1, 4), ('', 1, NULL, 10, NULL, 5), ('A', 5, 1, 1, 10, 6), (' 1', 1, 3.1, 5, 1, 7);
CREATE TABLE t3 (c1 INT, c2 INT, c3 INT, c6 INT, c7 INT, c8 BIGINT, c9 DOUBLE) ENGINE=InnoDB;
INSERT INTO t3 VALUES (3, 7, 10, 0, 2, 5, 3), (4, 4, 3, 2, -1, -3, 1), (2, 5, NULL, 1, 1, 1, NULL), (0, 5, NULL, 3, 4, 4, 1), (2, 0, 1, 2, 4, -3, 3), (7, 2, 2, 0, 1, NULL, 0), (2, 5, 0, 5, -3, -1, NULL), (-3, 2, 0, 2, 7, NULL, 2.1), (1, 1, 7, 10, -1, NULL, 5), (3, 3, 1, 7, 4, 2, -1), (4, 10, -1, NULL, NULL, -1, NULL), (1, 2, 4, -1, 2, -1, 10), (7, -3, -3, -3, -1, 4, 5.25), (2, 5, 5, 5, 0, 3, 1.1);
CREATE INDEX i0 ON t3 (c8, c2, c6);
CREATE INDEX i1 ON t2 (c15, c14);
ANALYZE TABLE t1;
ANALYZE TABLE t2;
ANALYZE TABLE t3;
SELECT 'seed 4 original' AS q;
(SELECT (t1a.c1 % 2) AS k0, t1a.c1 AS k1 FROM t1 AS t1a) INTERSECT (SELECT MAX((t3a.c7 - 3)) AS k0, MIN((t3a.c2 + t3a.c2)) AS k1 FROM t3 AS t3a WHERE NOT (EXISTS (SELECT t1s48.c1 FROM t1 AS t1s48 WHERE t1s48.c4 IS NULL)) HAVING (SUM(t3a.c3)) >= 2);
SELECT 'seed 4 mutant' AS q;
(SELECT (t1a.c1 % 2) AS k0, t1a.c1 AS k1 FROM t1 AS t1a) INTERSECT (SELECT MAX((t3a.c7 - 3)) AS k0, MIN((t3a.c2 + t3a.c2)) AS k1 FROM t3 AS t3a WHERE NOT (EXISTS (SELECT t1s48.c1 FROM t1 AS t1s48 WHERE t1s48.c4 IS NULL)) HAVING 1 = 0);
SELECT 'seed 4 arm 1' AS q;
SELECT MAX((t3a.c7 - 3)) AS k0, MIN((t3a.c2 + t3a.c2)) AS k1 FROM t3 AS t3a WHERE NOT (EXISTS (SELECT t1s48.c1 FROM t1 AS t1s48 WHERE t1s48.c4 IS NULL)) HAVING 1 = 0;
SELECT 'seed 4 arm 2' AS q;
SELECT MAX((t3a.c7 - 3)) AS k0, MIN((t3a.c2 + t3a.c2)) AS k1 FROM t3 AS t3a WHERE NOT (EXISTS (SELECT t1s48.c1 FROM t1 AS t1s48 WHERE t1s48.c4 IS NULL));
SELECT 'seed 4 arm 3' AS q;
SELECT DISTINCT (t1a.c1 % 2) AS k0, t1a.c1 AS k1 FROM t1 AS t1a;
USE information_schema; DROP DATABASE vs_hf4;
DROP DATABASE IF EXISTS vs_hf5; CREATE DATABASE vs_hf5; USE vs_hf5;
CREATE TABLE t1 (c1 INT, c4 INT, rid INT PRIMARY KEY) ENGINE=InnoDB;
