CREATE TABLE t2 (c1 VARCHAR(20) COLLATE utf8mb4_bin, c2 INT, c3 DECIMAL(10,2), c14 DECIMAL(10,2), c15 VARCHAR(20) COLLATE utf8mb4_general_ci) ENGINE=InnoDB;
INSERT INTO t2 VALUES ('a', -3, 1, 2, '1'), ('1', 7, NULL, -0.5, '-1'), (NULL, 10, 5.5, 2.5, '0'), ('5', 5, -2.25, -0.75, NULL), ('x', 2, 1.75, -3, ' 1'), ('a', 2, 2, 2, ' 1'), (NULL, 1, NULL, 4.75, '2'), ('4', -3, NULL, 3, 'x'), ('3', 4, -3, 1.75, 'b'), ('A', 7, 0, 2.25, ' 1'), ('a', 2, NULL, 5, '-3'), ('-3', 0, 2.75, 3, 'A'), ('b', 4, 2, 0, NULL), (NULL, NULL, 1, 5, '01'), ('7', 10, -3, 2.75, 'B'), ('x', 7, 5.75, 1, 'a'), ('a', NULL, 2, NULL, '10'), ('x', NULL, 5.5, 1, 'a ');
CREATE TABLE t3 (c1 VARCHAR(20) COLLATE utf8mb4_general_ci, c2 INT, c3 VARCHAR(20) COLLATE utf8mb4_general_ci, c6 INT, c7 INT, c8 VARCHAR(20) COLLATE utf8mb4_bin, c9 BIGINT) ENGINE=InnoDB;
INSERT INTO t3 VALUES (NULL, 7, 'b', -1, 1, '7', 2), ('b', 5, '-1', 7, 7, '2', 3), ('4', 1, '10', -3, 4, '01', 0), (NULL, NULL, ' 1', 1, 2, 'A', 7), (' 1', -1, '4', 4, 5, '1', -1), (' 1', 4, 'b', -1, 7, '4', 0), ('', 10, NULL, 10, 5, '1', 3), ('3', 2, 'B', 2, -3, NULL, 10), ('4', 3, NULL, 3, 5, 'x', -1);
CREATE INDEX i0 ON t1 (c4);
CREATE INDEX i1 ON t3 (c9, c1);
CREATE INDEX i2 ON t1 (c1, c4);
CREATE INDEX i3 ON t1 (c1, c4);
ANALYZE TABLE t1;
ANALYZE TABLE t2;
ANALYZE TABLE t3;
SELECT 'seed 5 original' AS q;
(SELECT (MIN((t1a.c4 + t1a.c1)) + 7) AS k0, COUNT(DISTINCT t1a.c1) AS k1 FROM t1 AS t1a) INTERSECT (SELECT t1a.c1 AS k0, t1a.c4 AS k1 FROM t1 AS t1a WHERE (t1a.c1 = 5) OR (t1a.c4 = 0));
SELECT 'seed 5 mutant' AS q;
(SELECT (MIN((t1a.c4 + t1a.c1)) + 7) AS k0, COUNT(DISTINCT t1a.c1) AS k1 FROM t1 AS t1a HAVING 1 = 0) INTERSECT (SELECT t1a.c1 AS k0, t1a.c4 AS k1 FROM t1 AS t1a WHERE (t1a.c1 = 5) OR (t1a.c4 = 0));
SELECT 'seed 5 arm 1' AS q;
SELECT (MIN((t1a.c4 + t1a.c1)) + 7) AS k0, COUNT(DISTINCT t1a.c1) AS k1 FROM t1 AS t1a HAVING 1 = 0;
SELECT 'seed 5 arm 2' AS q;
SELECT (MIN((t1a.c4 + t1a.c1)) + 7) AS k0, COUNT(DISTINCT t1a.c1) AS k1 FROM t1 AS t1a;
SELECT 'seed 5 arm 3' AS q;
SELECT t1a.c1 AS k0, t1a.c4 AS k1 FROM t1 AS t1a WHERE (t1a.c1 = 5) OR (t1a.c4 = 0);
USE information_schema; DROP DATABASE vs_hf5;
