(SELECT t3a.c9 AS k0 FROM t3 AS t3a) EXCEPT (SELECT SIGN(COUNT(t3a.c9)) AS k0 FROM t3 AS t3a HAVING 1 = 0);
SELECT 'seed 7 arm 1' AS q;
SELECT SIGN(COUNT(t3a.c9)) AS k0 FROM t3 AS t3a HAVING 1 = 0;
SELECT 'seed 7 arm 2' AS q;
SELECT SIGN(COUNT(t3a.c9)) AS k0 FROM t3 AS t3a HAVING (COUNT(DISTINCT t3a.c9 - 1)) <> (-1);
